static void serialpl011_tx_pump(struct serialpl011_priv *priv)
{
	struct tty_port *tport = &priv->port.state->port;
	unsigned char __ch;

	/* High-priority XON/XOFF: sent even when TX is stopped. If the FIFO has no
	 * space yet, leave TxReady armed (return WITHOUT disarming) so the level TX
	 * IRQ refires — never strand a pending x_char (Codex M2 follow-up 1). */
	if (priv->port.x_char) {
		if (!serialpl011_data_ready_query(&priv->inner, (struct ReadyDir){ ._raw = { [0] = 0x0 } }))
			return;
		serialpl011_data_unit_write(&priv->inner, priv->port.x_char);
		priv->port.x_char = 0;
		priv->port.icount.tx++;
	}
	/* Disarm TxReady when the core STOPPED TX (CTS/XOFF) OR the queue drained —
	 * BOTH cases, so a stopped non-empty queue does not leave TxReady armed (a
	 * level-IRQ storm; Codex M2 follow-up 2). The core re-kicks via start_tx. */
	if (kfifo_is_empty(&tport->xmit_fifo) || uart_tx_stopped(&priv->port)) {
		serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x0 } }, (struct IrqSourceState){ ._raw = { [0] = 0x1 } });
		return;
	}
	while (serialpl011_data_ready_query(&priv->inner, (struct ReadyDir){ ._raw = { [0] = 0x0 } })) {
		if (!kfifo_peek(&tport->xmit_fifo, &__ch))
			break;
		serialpl011_data_unit_write(&priv->inner, __ch);
		uart_xmit_advance(&priv->port, 1);
	}
	if (kfifo_len(&tport->xmit_fifo) < WAKEUP_CHARS)
		uart_write_wakeup(&priv->port);
	if (kfifo_is_empty(&tport->xmit_fifo))
		serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x0 } }, (struct IrqSourceState){ ._raw = { [0] = 0x1 } });
}

/* the synthesized serial ISR (construct #7, B3): decode -> dispatch over the
 * construct data path. No authored #[rseq::isr]; the compiler owns the line
 * handler for a serial driver. */
static irqreturn_t serialpl011_isr(int irq, void *dev_id)
{
	struct serialpl011_priv *priv = dev_id;
	struct tty_port *tport = &priv->port.state->port;
	struct CauseSet __c;

	uart_port_lock(&priv->port);
	__c = serialpl011_irq_cause_decode(&priv->inner);
	if ((__c.bits & 14u) != 0u) {
		while (serialpl011_data_ready_query(&priv->inner, (struct ReadyDir){ ._raw = { [0] = 0x1 } })) {
			struct RxDatum __d = serialpl011_data_unit_read(&priv->inner);
			unsigned int __e = __d.errors.bits;
			unsigned int __flag = TTY_NORMAL;
			priv->port.icount.rx++;
			if (__e & 16u) { priv->port.icount.brk++; __flag = TTY_BREAK; }
			else if (__e & 2u) { priv->port.icount.parity++; __flag = TTY_PARITY; }
			else if (__e & 1u) { priv->port.icount.frame++; __flag = TTY_FRAME; }
			if (__e & 8u) priv->port.icount.buf_overrun++;
			tty_insert_flip_char(tport, __d.unit & 0xff, __flag);
			if (__e & 4u) { priv->port.icount.overrun++; tty_insert_flip_char(tport, 0, TTY_OVERRUN); }
		}
	}
	if ((__c.bits & 1u) != 0u)
		serialpl011_tx_pump(priv);
	uart_port_unlock(&priv->port);
	tty_flip_buffer_push(tport);
	return IRQ_RETVAL((__c.bits) != 0u);
}

static int serialpl011_startup(struct uart_port *port)
{
	struct serialpl011_priv *priv = serialpl011_of(port);
	int ret;

	ret = request_irq(port->irq, serialpl011_isr, 0, "serialpl011", priv);
	if (ret)
		return ret;
	/* per-source arming (Linux `startup` WHEN, R04): arm RX + line-error */
	serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x1 } }, (struct IrqSourceState){ ._raw = { [0] = 0x0 } });
	serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x2 } }, (struct IrqSourceState){ ._raw = { [0] = 0x0 } });
	return 0;
}

static void serialpl011_shutdown(struct uart_port *port)
{
	struct serialpl011_priv *priv = serialpl011_of(port);
	/* mask all sources (Linux `shutdown` WHEN, R04) */
	serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x0 } }, (struct IrqSourceState){ ._raw = { [0] = 0x1 } });
	serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x1 } }, (struct IrqSourceState){ ._raw = { [0] = 0x1 } });
	serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x2 } }, (struct IrqSourceState){ ._raw = { [0] = 0x1 } });
	free_irq(port->irq, priv);
	serialpl011_port_service_set(&priv->inner, (struct PortScope){ ._raw = { [0] = 0x0 } }, false);
}

static void serialpl011_start_tx(struct uart_port *port)
{
	struct serialpl011_priv *priv = serialpl011_of(port);
	serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x0 } }, (struct IrqSourceState){ ._raw = { [0] = 0x0 } });
	serialpl011_tx_pump(priv);
}

static void serialpl011_stop_tx(struct uart_port *port)
{
	struct serialpl011_priv *priv = serialpl011_of(port);
	serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x0 } }, (struct IrqSourceState){ ._raw = { [0] = 0x1 } });
}

static void serialpl011_stop_rx(struct uart_port *port)
{
	struct serialpl011_priv *priv = serialpl011_of(port);
	serialpl011_irq_source_set(&priv->inner, (struct SerialIrqSource){ ._raw = { [0] = 0x1 } }, (struct IrqSourceState){ ._raw = { [0] = 0x1 } });
}

static unsigned int serialpl011_tx_empty(struct uart_port *port)
{
	struct serialpl011_priv *priv = serialpl011_of(port);
	return serialpl011_tx_drain_query(&priv->inner) ? TIOCSER_TEMT : 0;
}

static void serialpl011_set_termios(struct uart_port *port, struct ktermios *termios,
				  const struct ktermios *old)
{
	struct serialpl011_priv *priv = serialpl011_of(port);
	unsigned long flags;
	unsigned int baud;
	struct LineFormat lf;
	struct ConfigResult __r;

	baud = uart_get_baud_rate(port, termios, old, 0, port->uartclk / 16);
	lf.baud = baud;
	switch (termios->c_cflag & CSIZE) {
	case CS5: lf.data_bits = (struct DataBits){ ._raw = { [0] = 0x0 } }; break;
	case CS6: lf.data_bits = (struct DataBits){ ._raw = { [0] = 0x1 } }; break;
	case CS7: lf.data_bits = (struct DataBits){ ._raw = { [0] = 0x2 } }; break;
	default:  lf.data_bits = (struct DataBits){ ._raw = { [0] = 0x3 } }; break;
	}
	if (termios->c_cflag & PARENB)
		lf.parity = (termios->c_cflag & PARODD) ? (struct Parity){ ._raw = { [0] = 0x2 } } : (struct Parity){ ._raw = { [0] = 0x1 } };
	else
		lf.parity = (struct Parity){ ._raw = { [0] = 0x0 } };
	lf.stop_bits = (termios->c_cflag & CSTOPB) ? (struct StopBits){ ._raw = { [0] = 0x1 } } : (struct StopBits){ ._raw = { [0] = 0x0 } };

	uart_port_lock_irqsave(port, &flags);
	uart_update_timeout(port, termios->c_cflag, baud);
	/* PL011 §3.3.8: reprogram LCR_H/IBRD/FBRD only while the port is disabled */
	serialpl011_port_service_set(&priv->inner, (struct PortScope){ ._raw = { [0] = 0x0 } }, false);
	__r = serialpl011_line_format_apply(&priv->inner, lf);
	serialpl011_port_service_set(&priv->inner, (struct PortScope){ ._raw = { [0] = 0x0 } }, true);
	/* ConfigResult::Unsupported is SURFACED, not silently defaulted (I03):
	 * revert to the prior termios so userspace observes the rejection. */
	if (__r._raw[0] == 0x1 && old)
		*termios = *old;
	uart_port_unlock_irqrestore(port, flags);
}

